"""Canonical hymns: patterns (on normalized Arabic) -> one hymn with its place in the library.

Each rule: (pattern, key, english, arabic, places, existing id or None, note)
First match wins, so specific patterns come before general ones.
"check" in the note means the placement is a guess to confirm.
"""
import re

def norm(s):
    s = re.sub('[ً-ٰٟـ]', '', s)          # tashkeel, tatweel
    s = s.translate(str.maketrans('أإآٱىةؤئ', 'ااااايهوي'[:0] + 'ااااي' + 'ه' + 'وي'))
    s = s.replace('ـ', '')
    s = re.sub(r'\s+', ' ', s)
    return s.strip()

