RULES = [(re.compile(norm(p)), k, en, ar, pl, ex, note) for p, k, en, ar, pl, ex, note in R]

def classify(name):
    n = norm(name)
    for rx, k, en, ar, pl, ex, note in RULES:
        if rx.search(n):
            return dict(key=k, english=en, arabic=ar, places=pl, existing=ex, note=note)
    return None
